const Q_TYPE_OPTIONS = ["SHORT ANSWER", "LONG ANSWER", "SONG LIST", "SINGLE SELECT", "MULTI SELECT"];

const inferQType = (q) => {
  if (q.type) return String(q.type).toUpperCase();
  const t = (q.q || "").toLowerCase();
  if (/must-play|song|playlist|first dance|last song/.test(t)) return "SONG LIST";
  if (/describe|avoid|else|notes|anything/.test(t)) return "LONG ANSWER";
  if (/vibe|prefer|how did|microphone|needed/.test(t)) return "SINGLE SELECT";
  return "SHORT ANSWER";
};

const tplField = {
  width: "100%", boxSizing: "border-box", padding: "9px 12px",
  border: `1px solid ${C.border}`, borderRadius: BRAND_RADIUS.field, background: C.surfaceAlt,
  fontSize: 13, fontFamily: BRAND_FONT, color: C.text, outline: "none",
};

const Templates = ({ setSection }) => {
  const {
    contractTemplates, setContractTemplates, contracts,
    customQuestionnaires, setCustomQuestionnaires, questionnaireInstances,
    timelineTemplates, setTimelineTemplates,
    musicTemplates, setMusicTemplates,
    events, setEvents, setTimelines,
    customEventTypes,
  } = useApp();
  const [browseKind, setBrowseKind] = useState(null); // null = hub, else category browse
  const [search, setSearch] = useState("");
  const [activeKey, setActiveKey] = useState(null);
  const [draft, setDraft] = useState(null);
  const [showNew, setShowNew] = useState(false);
  const [showUseEvent, setShowUseEvent] = useState(false);
  const [toast, setToast] = useState(null);
  const [hovId, setHovId] = useState(null);
  const [dirty, setDirty] = useState(false);
  // Contracts use the classic ContractTemplateEditor (not the Templates detail view)
  const [editingContractTemplate, setEditingContractTemplate] = useState(null); // null | "new" | id

  const timelineList = (timelineTemplates != null && timelineTemplates.length > 0)
    ? timelineTemplates
    : (TIMELINE_TEMPLATES || []).map((t) => enrichTimelineTemplate(t, TIMELINE_DISPLAY_SEED[t.id] || {}));
  const musicList = (musicTemplates != null && musicTemplates.length > 0) ? musicTemplates : DEFAULT_MUSIC_TEMPLATES;
  const contractList = (contractTemplates != null && contractTemplates.length > 0) ? contractTemplates : DEFAULT_TEMPLATES;
  const qList = (customQuestionnaires && customQuestionnaires.length > 0) ? customQuestionnaires : DEFAULT_Q_TEMPLATES;

  const library = [];
  (timelineList || []).forEach((t) => {
    library.push({
      key: `timeline:${t.id}`,
      kind: "timeline",
      id: t.id,
      name: t.name,
      desc: t.desc || "",
      favorite: !!t.favorite,
      used: t.used || 0,
      edited: t.edited || "—",
      raw: t,
      metaBits: [`${(t.items || []).length} blocks`],
    });
  });
  (contractList || []).forEach((t) => {
    const meta = CONTRACT_DISPLAY[t.id] || {};
    const liveUsed = (contracts || []).filter((c) => c.templateId === t.id || c.template === t.name).length;
    const clauses = (t.body || "").split(/\n\s*\d+\.\s+/).filter(Boolean).length;
    library.push({
      key: `contract:${t.id}`,
      kind: "contract",
      id: t.id,
      name: meta.name || t.name,
      desc: meta.desc || t.desc || `${t.type || "Event"} contract template.`,
      favorite: t.favorite ?? meta.favorite ?? (t.id === "wedding"),
      used: liveUsed || meta.used || 0,
      edited: t.edited || meta.edited || "—",
      raw: { ...t, name: meta.name || t.name, desc: meta.desc || t.desc || "" },
      metaBits: [`${Math.max(clauses - 1, 1)} clauses`],
    });
  });
  (musicList || []).forEach((t) => {
    const songCount = (t.sections || []).reduce((s, sec) => s + (sec.songs || []).length, 0);
    library.push({
      key: `music:${t.id}`,
      kind: "music",
      id: t.id,
      name: t.name,
      desc: t.desc || "",
      favorite: !!t.favorite,
      used: t.used || 0,
      edited: t.edited || "—",
      raw: t,
      metaBits: [`${(t.sections || []).length} sets`, `${songCount} songs`],
    });
  });
  (qList || []).forEach((t) => {
    const liveUsed = (questionnaireInstances || []).filter((q) => q.templateId === t.id).length;
    const qCount = (t.questions || []).length;
    library.push({
      key: `questionnaire:${t.id}`,
      kind: "questionnaire",
      id: t.id,
      name: t.name.includes("Questionnaire") || /preferences/i.test(t.name) ? t.name : `${t.name} Questionnaire`,
      desc: t.desc || `${qCount} questions — collect details before the gig.`,
      favorite: t.favorite ?? (t.id === "wedding"),
      used: liveUsed || ({ wedding: 41, corporate: 18, birthday: 24, club: 9 }[t.id] || 6),
      edited: t.edited || ({ wedding: "1d ago", corporate: "4d ago", birthday: "2d ago", club: "1w ago" }[t.id] || "—"),
      raw: {
        ...t,
        questions: (t.questions || []).map((q) => ({
          ...q,
          type: inferQType(q),
          required: q.required ?? /must|first dance|vibe/i.test(q.q || ""),
          options: q.options || (inferQType(q) === "SINGLE SELECT" ? ["Option A", "Option B", "Option C"] : []),
        })),
      },
      metaBits: [`${qCount} questions`],
    });
  });

  const counts = {
    all: library.length,
    timeline: library.filter((i) => i.kind === "timeline").length,
    contract: library.filter((i) => i.kind === "contract").length,
    music: library.filter((i) => i.kind === "music").length,
    questionnaire: library.filter((i) => i.kind === "questionnaire").length,
  };
  const totalUsed = library.reduce((s, i) => s + (Number(i.used) || 0), 0);
  const filtered = library.filter((i) => {
    if (browseKind && i.kind !== browseKind) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return i.name.toLowerCase().includes(q) || i.desc.toLowerCase().includes(q) || i.kind.includes(q);
  });

  const openDetail = (item) => {
    if (item.kind === "contract") {
      setBrowseKind("contract");
      setActiveKey(null);
      setDraft(null);
      setDirty(false);
      setEditingContractTemplate(item.id);
      return;
    }
    setBrowseKind(item.kind);
    setActiveKey(item.key);
    const raw = item.raw || {};
    setDraft(JSON.parse(JSON.stringify({
      key: item.key,
      kind: item.kind,
      id: item.id,
      name: item.name,
      desc: item.desc,
      favorite: item.favorite,
      used: item.used,
      edited: item.edited,
      ...raw,
      items: raw.items ? raw.items.map(normalizeTimelineItem) : raw.items,
      sections: item.kind === "music"
        ? (raw.sections || []).map(normalizeMusicSection)
        : raw.sections,
      questions: raw.questions,
      body: raw.body,
      type: raw.type,
      eventType: raw.eventType || raw.type || (item.kind === "music" ? "Wedding" : undefined),
    })));
    setDirty(false);
  };

  const updateDraft = (patch) => {
    setDraft((d) => ({ ...d, ...patch }));
    setDirty(true);
  };

  const saveDraft = () => {
    if (!draft) return;
    const stamped = { ...draft, edited: "Just now" };
    if (draft.kind === "timeline") {
      const next = (timelineList || []).map((t) => (t.id === draft.id ? {
        id: draft.id, name: draft.name, desc: draft.desc, favorite: draft.favorite,
        used: draft.used, edited: stamped.edited, type: draft.type,
        items: (draft.items || []).map(normalizeTimelineItem),
      } : t));
      const exists = next.some((t) => t.id === draft.id);
      setTimelineTemplates(exists ? next : [...next, {
        id: draft.id, name: draft.name, desc: draft.desc, favorite: !!draft.favorite,
        used: draft.used || 0, edited: stamped.edited, type: draft.type || "",
        items: (draft.items || []).map(normalizeTimelineItem),
      }]);
    } else if (draft.kind === "music") {
      const row = {
        id: draft.id,
        name: draft.name,
        desc: draft.desc,
        favorite: draft.favorite,
        used: draft.used,
        edited: stamped.edited,
        eventType: draft.eventType || "Wedding",
        sections: (draft.sections || []).map(normalizeMusicSection),
      };
      const next = (musicList || []).map((t) => (t.id === draft.id ? { ...t, ...row } : t));
      const exists = next.some((t) => t.id === draft.id);
      setMusicTemplates(exists ? next : [...next, { ...row, used: draft.used || 0 }]);
    } else if (draft.kind === "contract") {
      const base = contractTemplates != null ? [...contractTemplates] : [...DEFAULT_TEMPLATES];
      const idx = base.findIndex((t) => t.id === draft.id);
      const row = { id: draft.id, name: draft.name, type: draft.type || "Custom", body: draft.body || "", desc: draft.desc, favorite: draft.favorite, edited: stamped.edited };
      if (idx >= 0) base[idx] = { ...base[idx], ...row };
      else base.push(row);
      setContractTemplates(base);
    } else if (draft.kind === "questionnaire") {
      const base = (customQuestionnaires && customQuestionnaires.length > 0) ? [...customQuestionnaires] : [...DEFAULT_Q_TEMPLATES];
      const idx = base.findIndex((t) => t.id === draft.id);
      const row = {
        id: draft.id,
        name: draft.name,
        desc: draft.desc,
        favorite: draft.favorite,
        edited: stamped.edited,
        sections: draft.sections || [{ id: "General", label: "General", desc: "" }],
        questions: (draft.questions || []).map((q, i) => ({
          id: q.id || i + 1,
          q: q.q || "",
          section: q.section || "General",
          type: q.type || "SHORT ANSWER",
          required: !!q.required,
          options: q.options || [],
        })),
      };
      if (idx >= 0) base[idx] = { ...base[idx], ...row };
      else base.push(row);
      setCustomQuestionnaires(base);
    }
    setDraft(stamped);
    setDirty(false);
    setToast("Template saved");
  };

  const duplicateDraft = () => {
    if (!draft) return;
    const nid = `${draft.id}-copy-${Date.now().toString(36).slice(-4)}`;
    const copy = {
      ...JSON.parse(JSON.stringify(draft)),
      id: nid,
      key: `${draft.kind}:${nid}`,
      name: `${draft.name} (Copy)`,
      used: 0,
      edited: "Just now",
      favorite: false,
    };
    setDraft(copy);
    setActiveKey(copy.key);
    setDirty(true);
    setToast("Duplicated — hit Save to keep it");
  };

  const createBlank = (kind) => {
    if (kind === "contract") {
      setShowNew(false);
      setBrowseKind("contract");
      setActiveKey(null);
      setDraft(null);
      setDirty(false);
      setEditingContractTemplate("new");
      return;
    }
    const id = `new-${kind}-${Date.now().toString(36).slice(-5)}`;
    const blanks = {
      timeline: {
        key: `timeline:${id}`, kind: "timeline", id, name: "Untitled Timeline",
        desc: "Describe this run-of-show…", favorite: false, used: 0, edited: "Just now",
        type: "Custom", items: [normalizeTimelineItem({ time: "6:00 PM", duration: "30 min", label: "First moment", note: "", tag: "CUSTOM" }, 0)],
      },
      music: {
        key: `music:${id}`, kind: "music", id, name: "Wedding Set List",
        desc: "Cocktail through last dance — edit vibes per block.", favorite: false, used: 0, edited: "Just now",
        eventType: "Wedding",
        sections: sectionsFromStarters("Wedding"),
      },
      questionnaire: {
        key: `questionnaire:${id}`, kind: "questionnaire", id, name: "Untitled Questionnaire",
        desc: "Questions for your client…", favorite: false, used: 0, edited: "Just now",
        sections: [{ id: "General", label: "General", desc: "" }],
        questions: [{ id: 1, q: "New question", section: "General", type: "SHORT ANSWER", required: false, options: [] }],
      },
    };
    setShowNew(false);
    setBrowseKind(kind);
    setDraft(blanks[kind]);
    setActiveKey(blanks[kind].key);
    setDirty(true);
  };

  const applyToEvent = (ev) => {
    if (!draft || !ev) return;
    if (draft.kind === "timeline") {
      const items = (draft.items || []).map((m, i) => ({
        id: Date.now() + i,
        time: m.time || "",
        label: m.label || "",
        note: m.note || "",
        tag: m.tag || "",
        duration: m.duration || "",
      }));
      setTimelines((prev) => ({ ...(prev || {}), [ev.id]: items }));
      setToast(`Timeline applied to ${ev.name}`);
    } else if (draft.kind === "music") {
      setEvents((prev) => (prev || []).map((e) => String(e.id) === String(ev.id) ? {
        ...e,
        music: {
          ...(e.music || {}),
          templateId: draft.id,
          sections: (draft.sections || []).map((s) => ({
            name: s.name,
            startTime: s.startTime,
            songs: (s.songs || []).map((song) => ({
              title: song.title || "",
              artist: song.artist || "",
              bpm: song.bpm || "",
              duration: song.duration || "",
            })),
          })),
        },
      } : e));
      setToast(`Set list applied to ${ev.name}`);
    } else if (draft.kind === "contract") {
      setSection?.("contracts");
      setToast(`Open Contracts to send “${draft.name}” for ${ev.name}`);
    } else if (draft.kind === "questionnaire") {
      setSection?.("questionnaires");
      setToast(`Open Questionnaires to send “${draft.name}” for ${ev.name}`);
    }
    setShowUseEvent(false);
  };

  // ── CLASSIC CONTRACT EDITOR (same as Contracts → Templates) ──
  if (editingContractTemplate !== null) {
    const tpl = editingContractTemplate === "new"
      ? null
      : (contractList || []).find((t) => t.id === editingContractTemplate) || null;
    return (
      <>
        {toast && <Toast message={toast} onClose={() => setToast(null)} />}
        <ContractTemplateEditor
          template={tpl}
          onSave={(saved) => {
            setContractTemplates((prev) => {
              const current = prev != null ? prev : [...DEFAULT_TEMPLATES];
              const exists = current.find((t) => t.id === saved.id);
              const row = { ...saved, edited: "Just now" };
              return exists ? current.map((t) => (t.id === saved.id ? { ...t, ...row } : t)) : [...current, row];
            });
            setToast("Template saved!");
          }}
          onClose={() => {
            setEditingContractTemplate(null);
            setBrowseKind("contract");
          }}
        />
      </>
    );
  }

  // ── NEW MUSIC SET EDITOR ─────────────────────────────────
  if (draft && activeKey && draft.kind === "music") {
    const meta = TEMPLATE_KIND_META.music;
    const isNew = String(draft.id || "").startsWith("new-music");
    const eventType = draft.eventType || "Wedding";
    const sections = (draft.sections || []).map(normalizeMusicSection);
    const starters = musicStartersFor(eventType);
    const existingNames = new Set(sections.map((s) => (s.name || "").trim().toLowerCase()).filter(Boolean));
    const quickAdds = starters.filter((s) => !existingNames.has(s.name.toLowerCase()));

    const eventTypeOptions = (() => {
      const fromPrefs = (customEventTypes || DEFAULT_EVENT_TYPES || []).map((t) => t.id || t).filter(Boolean);
      const merged = [...MUSIC_EVENT_TYPES];
      fromPrefs.forEach((t) => { if (!merged.includes(t) && !MUSIC_EVENT_TYPES.includes(t)) merged.push(t); });
      return merged;
    })();

    const setSections = (next) => updateDraft({ sections: next.map(normalizeMusicSection) });

    const moveSection = (idx, dir) => {
      const next = [...sections];
      const j = idx + dir;
      if (j < 0 || j >= next.length) return;
      [next[idx], next[j]] = [next[j], next[idx]];
      setSections(next);
    };

    const addQuickSection = (preset) => {
      setSections([...sections, blankMusicSection({
        name: preset.name,
        energy: preset.energy,
        notes: preset.notes,
        tags: [preset.energy],
      })]);
    };

    const applyEventType = (nextType) => {
      const blank = musicSectionsAreBlank(sections);
      const patch = { eventType: nextType };
      if (blank || isNew) {
        patch.sections = sectionsFromStarters(nextType);
        if (!draft.name || /^untitled/i.test(draft.name) || /set list$/i.test(draft.name)) {
          patch.name = `${nextType} Set List`;
        }
        if (!draft.desc || /cocktail through|edit vibes/i.test(draft.desc)) {
          patch.desc = nextType === "Wedding"
            ? "Cocktail through last dance — edit vibes per block."
            : `Music blocks for a ${nextType.toLowerCase()} — edit vibes per block.`;
        }
      }
      updateDraft(patch);
    };

    const resetToStarter = () => {
      if (sections.some((s) => (s.name || "").trim()) && !confirm(`Replace sections with the ${eventType} starter blocks? Your current section list will be overwritten.`)) return;
      updateDraft({
        sections: sectionsFromStarters(eventType),
        name: draft.name && !/^untitled/i.test(draft.name) ? draft.name : `${eventType} Set List`,
      });
      setToast(`Loaded ${eventType} starter sections`);
    };

    const closeEditor = () => {
      if (dirty && !confirm("Discard unsaved changes?")) return;
      setActiveKey(null);
      setDraft(null);
      setDirty(false);
      setBrowseKind("music");
    };

    return (
      <div>
        {toast && <Toast message={toast} onClose={() => setToast(null)} />}
        {showUseEvent && (
          <Modal title="Use in Event" subtitle="Pick an event to apply this set list" onClose={() => setShowUseEvent(false)} width={480}>
            <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 360, overflow: "auto" }}>
              {(events || []).length === 0 && <div style={{ color: C.muted, fontSize: 13, padding: 12 }}>No events yet — create one first.</div>}
              {(events || []).map((ev) => (
                <button key={ev.id} onClick={() => applyToEvent(ev)} style={{
                  textAlign: "left", padding: "12px 14px", borderRadius: 12, border: `1px solid ${C.border}`,
                  background: C.surfaceAlt, cursor: "pointer", fontFamily: BRAND_FONT,
                }}>
                  <div style={{ fontWeight: 700, fontSize: 14, color: C.text }}>{ev.name}</div>
                  <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{ev.date || "No date"} · {ev.type || "Event"}</div>
                </button>
              ))}
            </div>
          </Modal>
        )}

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18, flexWrap: "wrap", gap: 12 }}>
          <div style={{ fontSize: 12, color: C.muted, fontFamily: BRAND_FONT }}>
            Event Templates
            <span style={{ margin: "0 6px", color: C.borderLight }}>›</span>
            <button onClick={closeEditor} style={{ background: "none", border: "none", color: C.muted, fontWeight: 600, cursor: "pointer", fontFamily: BRAND_FONT, padding: 0, fontSize: 12 }}>Music</button>
            <span style={{ margin: "0 6px", color: C.borderLight }}>›</span>
            <span style={{ color: C.text, fontWeight: 600 }}>{isNew ? "New Music Set" : (draft.name || "Music Set")}</span>
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Btn variant="ghost" onClick={closeEditor}>Cancel</Btn>
            <Btn variant="ghost" onClick={() => setShowUseEvent(true)}>Use in Event</Btn>
            <Btn onClick={saveDraft}>{dirty ? "Save Music" : "Saved"}</Btn>
          </div>
        </div>

        <div style={{
          background: C.surfaceAlt, border: `1px solid ${C.border}`, borderRadius: 16,
          padding: "28px 28px 32px", maxWidth: 720, boxShadow: "0 1px 4px rgba(22,22,26,0.04)",
        }}>
          <div style={{ display: "flex", gap: 14, alignItems: "flex-start", marginBottom: 22 }}>
            <div style={{
              width: 44, height: 44, borderRadius: 12, background: meta.soft, color: meta.color,
              display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
            }}>
              {meta.icon}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: "0.1em", color: meta.color, marginBottom: 6, fontFamily: BRAND_FONT }}>
                {isNew ? "NEW MUSIC SET" : "MUSIC SET"}
              </div>
              <input
                value={draft.name || ""}
                onChange={(e) => updateDraft({ name: e.target.value })}
                placeholder="Untitled set list"
                style={{
                  ...tplField, fontSize: 22, fontWeight: 900, letterSpacing: "-0.02em",
                  border: "1px solid transparent", background: "transparent", padding: "2px 0", marginBottom: 6,
                }}
                onFocus={(e) => { e.target.style.borderBottom = `1px solid ${C.border}`; }}
                onBlur={(e) => { e.target.style.border = "1px solid transparent"; }}
              />
              <input
                value={draft.desc || ""}
                onChange={(e) => updateDraft({ desc: e.target.value })}
                placeholder="Add a short description..."
                style={{
                  ...tplField, fontSize: 13, color: C.muted, border: "1px solid transparent",
                  background: "transparent", padding: "2px 0",
                }}
                onFocus={(e) => { e.target.style.borderBottom = `1px solid ${C.border}`; }}
                onBlur={(e) => { e.target.style.border = "1px solid transparent"; }}
              />
            </div>
          </div>

          <div style={{ marginBottom: 8, fontSize: 11, fontWeight: 800, letterSpacing: "0.08em", color: C.muted, fontFamily: BRAND_FONT }}>
            EVENT TYPE
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 8 }}>
            {eventTypeOptions.map((t) => {
              const on = eventType === t;
              return (
                <button key={t} type="button" onClick={() => applyEventType(t)}
                  style={{
                    padding: "8px 16px", borderRadius: 999, cursor: "pointer", fontFamily: BRAND_FONT,
                    fontSize: 13, fontWeight: on ? 700 : 500,
                    border: `1.5px solid ${on ? C.text : C.border}`,
                    background: on ? C.surfaceAlt : C.surface,
                    color: C.text,
                  }}>
                  {t}
                </button>
              );
            })}
          </div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 22, lineHeight: 1.5, fontFamily: BRAND_FONT }}>
            Sections are the music blocks you’ll play for this kind of gig — not every timeline moment.
            {musicSectionsAreBlank(sections) || isNew ? " Switching type reloads the starter blocks." : " Switching type keeps your sections; use Reset if you want the starter pack."}
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 18 }}>
            {sections.map((sec, sIdx) => (
              <div key={sec.id || sIdx} style={{
                display: "grid", gridTemplateColumns: "36px 1fr auto", gap: 12,
                background: "#fff", border: `1px solid ${C.border}`, borderRadius: 14, padding: "16px 16px 14px",
              }}>
                <div style={{
                  width: 32, height: 32, borderRadius: 10, background: C.surface,
                  border: `1px solid ${C.border}`, display: "flex", alignItems: "center", justifyContent: "center",
                  fontWeight: 800, fontSize: 13, color: C.muted, marginTop: 2,
                }}>{sIdx + 1}</div>
                <div style={{ minWidth: 0 }}>
                  <input
                    value={sec.name || ""}
                    placeholder="Section name (e.g. Cocktail Hour)"
                    onChange={(e) => {
                      const next = [...sections];
                      next[sIdx] = { ...next[sIdx], name: e.target.value };
                      setSections(next);
                    }}
                    style={{ ...tplField, fontWeight: 700, fontSize: 14, marginBottom: 8 }}
                  />
                  <input
                    value={sec.notes || ""}
                    placeholder="Vibe / genre notes (e.g. Chill — Motown, jazz standards)"
                    onChange={(e) => {
                      const next = [...sections];
                      next[sIdx] = { ...next[sIdx], notes: e.target.value };
                      setSections(next);
                    }}
                    style={{ ...tplField, fontSize: 13, color: C.muted, marginBottom: 12 }}
                  />
                  <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: "0.08em", color: C.muted, marginBottom: 8, fontFamily: BRAND_FONT }}>ENERGY</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                    {MUSIC_ENERGY_OPTIONS.map((opt) => {
                      const on = sec.energy === opt.id;
                      return (
                        <button key={opt.id} type="button"
                          onClick={() => {
                            const next = [...sections];
                            next[sIdx] = {
                              ...next[sIdx],
                              energy: opt.id,
                              tags: [opt.id, ...(next[sIdx].tags || []).filter((t) => !MUSIC_ENERGY_OPTIONS.some((e) => e.id === t))],
                            };
                            setSections(next);
                          }}
                          style={{
                            padding: "5px 12px", borderRadius: 999, cursor: "pointer", fontFamily: BRAND_FONT,
                            fontSize: 12, fontWeight: on ? 700 : 500,
                            border: `1.5px solid ${on ? opt.color : C.border}`,
                            background: on ? opt.soft : C.surface,
                            color: on ? opt.color : C.muted,
                          }}>
                          {opt.id}
                        </button>
                      );
                    })}
                  </div>
                  {(sec.songs || []).filter((s) => s.title || s.artist).length > 0 && (
                    <div style={{ marginTop: 12, fontSize: 12, color: C.muted, fontFamily: BRAND_FONT }}>
                      {(sec.songs || []).filter((s) => s.title || s.artist).length} song{(sec.songs || []).filter((s) => s.title || s.artist).length === 1 ? "" : "s"} kept on this section
                    </div>
                  )}
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
                  <button type="button" onClick={() => setSections(sections.filter((_, i) => i !== sIdx))}
                    style={{ background: "none", border: "none", color: C.red, cursor: "pointer", fontSize: 12, fontWeight: 600, fontFamily: BRAND_FONT }}>
                    Remove
                  </button>
                  <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                    <button type="button" onClick={() => moveSection(sIdx, -1)} disabled={sIdx === 0}
                      style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 6, width: 28, height: 24, cursor: sIdx === 0 ? "default" : "pointer", opacity: sIdx === 0 ? 0.35 : 1, color: C.muted }}>▲</button>
                    <button type="button" onClick={() => moveSection(sIdx, 1)} disabled={sIdx === sections.length - 1}
                      style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 6, width: 28, height: 24, cursor: sIdx === sections.length - 1 ? "default" : "pointer", opacity: sIdx === sections.length - 1 ? 0.35 : 1, color: C.muted }}>▼</button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {quickAdds.length > 0 && (
            <div style={{
              background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12,
              padding: "14px 16px", marginBottom: 16,
            }}>
              <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: "0.06em", color: C.muted, marginBottom: 6, fontFamily: BRAND_FONT }}>
                ADD {eventType.toUpperCase()} SECTION
              </div>
              <div style={{ fontSize: 12, color: C.muted, marginBottom: 10, fontFamily: BRAND_FONT }}>
                Only the blocks that fit this event type — skip what’s already on the list.
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                {quickAdds.map((preset) => (
                  <button key={preset.name} type="button" onClick={() => addQuickSection(preset)}
                    style={{
                      padding: "7px 12px", borderRadius: 8, border: `1px solid ${C.border}`,
                      background: "#fff", cursor: "pointer", fontFamily: BRAND_FONT,
                      fontSize: 12, fontWeight: 600, color: C.text,
                    }}>
                    + {preset.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
            <button
              type="button"
              onClick={() => setSections([...sections, blankMusicSection()])}
              style={{
                flex: 1, minWidth: 180, padding: "14px 16px", borderRadius: 12, cursor: "pointer",
                border: `1.5px dashed ${C.borderLight}`, background: "transparent",
                color: C.muted, fontWeight: 700, fontSize: 13, fontFamily: BRAND_FONT,
              }}
            >
              + Add custom section
            </button>
            <button
              type="button"
              onClick={resetToStarter}
              style={{
                padding: "14px 16px", borderRadius: 12, cursor: "pointer",
                border: `1px solid ${C.border}`, background: C.surface,
                color: C.text, fontWeight: 600, fontSize: 13, fontFamily: BRAND_FONT,
              }}
            >
              Reset to {eventType} starter
            </button>
          </div>

          <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.55, fontFamily: BRAND_FONT }}>
            Timelines stay in <strong style={{ color: C.text, fontWeight: 600 }}>Templates → Timelines</strong> for the minute-by-minute run of show.
            This set list is only the music blocks (vibe + energy) you’ll fill with songs later.
          </div>
        </div>
      </div>
    );
  }

  // ── DETAIL VIEW ──────────────────────────────────────────
  if (draft && activeKey && draft.kind !== "contract" && draft.kind !== "music") {
    const meta = TEMPLATE_KIND_META[draft.kind];
    const blockCount = draft.kind === "timeline" ? (draft.items || []).length
      : draft.kind === "music" ? (draft.sections || []).length
      : draft.kind === "questionnaire" ? (draft.questions || []).length
      : ((draft.body || "").match(/\n\s*\d+\.\s+/g) || []).length || 1;
    const songCount = (draft.sections || []).reduce((s, sec) => s + (sec.songs || []).length, 0);

    return (
      <div>
        {toast && <Toast message={toast} onClose={() => setToast(null)} />}
        {showUseEvent && (
          <Modal title="Use in Event" subtitle="Pick an event to apply this template" onClose={() => setShowUseEvent(false)} width={480}>
            <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 360, overflow: "auto" }}>
              {(events || []).length === 0 && <div style={{ color: C.muted, fontSize: 13, padding: 12 }}>No events yet — create one first.</div>}
              {(events || []).map((ev) => (
                <button key={ev.id} onClick={() => applyToEvent(ev)} style={{
                  textAlign: "left", padding: "12px 14px", borderRadius: 12, border: `1px solid ${C.border}`,
                  background: C.surfaceAlt, cursor: "pointer", fontFamily: BRAND_FONT,
                }}>
                  <div style={{ fontWeight: 700, fontSize: 14, color: C.text }}>{ev.name}</div>
                  <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{ev.date || "No date"} · {ev.type || "Event"}</div>
                </button>
              ))}
            </div>
          </Modal>
        )}

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, flexWrap: "wrap", gap: 10 }}>
          <button onClick={() => { if (dirty && !confirm("Discard unsaved changes?")) return; setActiveKey(null); setDraft(null); setDirty(false); setBrowseKind(draft.kind); }}
            style={{ background: "none", border: "none", color: C.muted, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: BRAND_FONT, padding: 0 }}>
            ← All {draft.kind === "questionnaire" ? "questionnaires" : draft.kind === "music" ? "music" : `${draft.kind}s`}
          </button>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Btn variant="ghost" onClick={duplicateDraft}>Duplicate</Btn>
            <Btn variant="ghost" onClick={() => setShowUseEvent(true)}>Use in Event</Btn>
            <Btn onClick={saveDraft} disabled={!dirty}>{dirty ? "Save changes" : "Saved"}</Btn>
          </div>
        </div>

        <div style={{ fontSize: 12, color: C.muted, marginBottom: 18, fontFamily: BRAND_FONT }}>
          Event Templates <span style={{ margin: "0 6px", color: C.borderLight }}>›</span> <span style={{ color: C.text, fontWeight: 600 }}>{draft.name}</span>
        </div>

        {/* Header */}
        <div style={{ display: "flex", gap: 14, alignItems: "flex-start", marginBottom: 24 }}>
          <div style={{ width: 40, height: 40, borderRadius: BRAND_RADIUS.icon, background: meta.soft, color: meta.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            {meta.icon}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", gap: 8, marginBottom: 8, flexWrap: "wrap", alignItems: "center" }}>
              <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: "0.06em", color: meta.color, background: meta.soft, padding: "4px 10px", borderRadius: 6, fontFamily: BRAND_FONT }}>{meta.label}</span>
              <button onClick={() => updateDraft({ favorite: !draft.favorite })} style={{
                display: "inline-flex", alignItems: "center", gap: 5, border: `1px solid ${C.border}`, background: draft.favorite ? "#FFFBEB" : C.surfaceAlt,
                borderRadius: BRAND_RADIUS.pill, padding: "4px 10px", cursor: "pointer", fontFamily: BRAND_FONT, fontSize: 11, fontWeight: 700, color: draft.favorite ? CATEGORY_TINTS.planning.text : C.muted,
              }}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill={draft.favorite ? "#EAB308" : "none"} stroke={draft.favorite ? "#EAB308" : "currentColor"} strokeWidth="2">
                  <path d="M12 2l2.9 6.6L22 10l-5 4.4L18.2 22 12 18.2 5.8 22 7 14.4 2 10l7.1-1.4L12 2z" />
                </svg>
                Favorite
              </button>
            </div>
            <input value={draft.name || ""} onChange={(e) => updateDraft({ name: e.target.value })}
              style={{ ...tplField, fontSize: 22, fontWeight: 900, letterSpacing: "-0.02em", border: "1px solid transparent", padding: "4px 8px", marginLeft: -8, marginBottom: 4, background: "transparent" }}
              onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = C.surfaceAlt; }}
              onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
            />
            <textarea value={draft.desc || ""} onChange={(e) => updateDraft({ desc: e.target.value })} rows={2}
              style={{ ...tplField, resize: "vertical", color: C.muted, fontSize: 13, border: "1px solid transparent", background: "transparent", marginLeft: -8 }}
              onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = C.surfaceAlt; }}
              onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
            />
            <div style={{ fontSize: 12, color: C.mutedLight, marginTop: 6, fontFamily: BRAND_FONT }}>
              Used in {draft.used || 0} events · Edited {draft.edited || "—"} · {draft.kind === "music" ? `${blockCount} sets · ${songCount} songs` : draft.kind === "timeline" ? `${blockCount} blocks` : `${blockCount} questions`}
            </div>
          </div>
        </div>

        {/* TIMELINE EDITOR */}
        {draft.kind === "timeline" && (
          <div style={{ position: "relative", paddingLeft: 4 }}>
            {(draft.items || []).map((item, idx) => {
              const tagMeta = TIMELINE_TAG_META[item.tag] || TIMELINE_TAG_META.CUSTOM;
              return (
                <div key={item.id || idx} style={{ display: "grid", gridTemplateColumns: "72px 28px 1fr", gap: 0, marginBottom: 12 }}>
                  <div style={{ paddingTop: 14, textAlign: "right", paddingRight: 10 }}>
                    <input value={item.time || ""} placeholder="5:30"
                      onChange={(e) => {
                        const items = [...(draft.items || [])];
                        items[idx] = { ...items[idx], time: e.target.value };
                        updateDraft({ items });
                      }}
                      style={{ ...tplField, padding: "4px 6px", fontWeight: 800, fontSize: 13, color: meta.color, textAlign: "right", border: "1px solid transparent", background: "transparent" }}
                      onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = "#fff"; }}
                      onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
                    />
                    <input value={item.duration || ""} placeholder="30 min"
                      onChange={(e) => {
                        const items = [...(draft.items || [])];
                        items[idx] = { ...items[idx], duration: e.target.value };
                        updateDraft({ items });
                      }}
                      style={{ ...tplField, padding: "2px 6px", fontSize: 11, color: C.muted, textAlign: "right", border: "1px solid transparent", background: "transparent", marginTop: 2 }}
                      onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = "#fff"; }}
                      onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
                    />
                  </div>
                  <div style={{ position: "relative", display: "flex", justifyContent: "center" }}>
                    <div style={{ position: "absolute", top: 0, bottom: idx === (draft.items || []).length - 1 ? "50%" : 0, width: 2, background: meta.soft }} />
                    <div style={{ width: 12, height: 12, borderRadius: "50%", background: meta.color, marginTop: 20, zIndex: 1, boxShadow: `0 0 0 4px ${meta.soft}` }} />
                  </div>
                  <div style={{ background: "#fff", border: `1px solid ${C.border}`, borderRadius: 14, padding: "14px 16px", display: "flex", gap: 12, alignItems: "flex-start" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <input value={item.label || ""} placeholder="Block title"
                        onChange={(e) => {
                          const items = [...(draft.items || [])];
                          items[idx] = { ...items[idx], label: e.target.value };
                          updateDraft({ items });
                        }}
                        style={{ ...tplField, fontWeight: 800, fontSize: 14, border: "1px solid transparent", background: "transparent", padding: "2px 4px" }}
                        onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = "#fff"; }}
                        onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
                      />
                      <textarea value={item.note || ""} placeholder="Notes for this block…" rows={2}
                        onChange={(e) => {
                          const items = [...(draft.items || [])];
                          items[idx] = { ...items[idx], note: e.target.value };
                          updateDraft({ items });
                        }}
                        style={{ ...tplField, marginTop: 4, fontSize: 12, color: C.muted, border: "1px solid transparent", background: "transparent", resize: "vertical", padding: "2px 4px" }}
                        onFocus={(e) => { e.target.style.border = `1px solid ${C.border}`; e.target.style.background = "#fff"; }}
                        onBlur={(e) => { e.target.style.border = "1px solid transparent"; e.target.style.background = "transparent"; }}
                      />
                    </div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 6, alignItems: "flex-end" }}>
                      <select value={item.tag || "CUSTOM"}
                        onChange={(e) => {
                          const items = [...(draft.items || [])];
                          items[idx] = { ...items[idx], tag: e.target.value };
                          updateDraft({ items });
                        }}
                        style={{ fontSize: 10, fontWeight: 800, letterSpacing: "0.05em", border: "none", borderRadius: 6, padding: "5px 8px", background: tagMeta.bg, color: tagMeta.color, fontFamily: BRAND_FONT, cursor: "pointer" }}>
                        {Object.keys(TIMELINE_TAG_META).map((k) => <option key={k} value={k}>{k}</option>)}
                      </select>
                      <button onClick={() => updateDraft({ items: (draft.items || []).filter((_, i) => i !== idx) })}
                        style={{ background: "none", border: "none", color: C.mutedLight, cursor: "pointer", fontSize: 12, fontFamily: BRAND_FONT }}>Remove</button>
                    </div>
                  </div>
                </div>
              );
            })}
            <Btn variant="ghost" size="sm" onClick={() => updateDraft({
              items: [...(draft.items || []), normalizeTimelineItem({ time: "", duration: "15 min", label: "New block", note: "", tag: "CUSTOM" }, (draft.items || []).length)],
            })}>+ Add block</Btn>
          </div>
        )}

        {/* QUESTIONNAIRE EDITOR */}
        {draft.kind === "questionnaire" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {(draft.questions || []).map((q, qIdx) => (
              <div key={q.id || qIdx} style={{ background: "#fff", border: `1px solid ${C.border}`, borderRadius: 14, padding: "16px 18px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 12, marginBottom: 10, flexWrap: "wrap" }}>
                  <div style={{ fontSize: 11, fontWeight: 800, color: C.mutedLight, letterSpacing: "0.06em" }}>QUESTION {String(qIdx + 1).padStart(2, "0")}</div>
                  <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                    <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: C.muted, fontWeight: 600, fontFamily: BRAND_FONT }}>
                      <input type="checkbox" checked={!!q.required} onChange={(e) => {
                        const questions = [...(draft.questions || [])];
                        questions[qIdx] = { ...questions[qIdx], required: e.target.checked };
                        updateDraft({ questions });
                      }} />
                      Required
                    </label>
                    <select value={q.type || "SHORT ANSWER"} onChange={(e) => {
                      const questions = [...(draft.questions || [])];
                      const type = e.target.value;
                      questions[qIdx] = {
                        ...questions[qIdx],
                        type,
                        options: (type === "SINGLE SELECT" || type === "MULTI SELECT")
                          ? (questions[qIdx].options?.length ? questions[qIdx].options : ["Option A", "Option B"])
                          : [],
                      };
                      updateDraft({ questions });
                    }} style={{ fontSize: 10, fontWeight: 800, letterSpacing: "0.05em", border: "none", borderRadius: 6, padding: "5px 8px", background: TEMPLATE_KIND_META.questionnaire.soft, color: TEMPLATE_KIND_META.questionnaire.color, fontFamily: BRAND_FONT, cursor: "pointer" }}>
                      {Q_TYPE_OPTIONS.map((t) => <option key={t} value={t}>{t}</option>)}
                    </select>
                    <button onClick={() => updateDraft({ questions: (draft.questions || []).filter((_, i) => i !== qIdx) })}
                      style={{ background: "none", border: "none", color: C.mutedLight, cursor: "pointer", fontSize: 12, fontFamily: BRAND_FONT }}>Remove</button>
                  </div>
                </div>
                <input value={q.q || ""} placeholder="Question text"
                  onChange={(e) => {
                    const questions = [...(draft.questions || [])];
                    questions[qIdx] = { ...questions[qIdx], q: e.target.value };
                    updateDraft({ questions });
                  }}
                  style={{ ...tplField, fontWeight: 700, fontSize: 14, marginBottom: 10 }}
                />
                <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
                  <input value={q.section || ""} placeholder="Section"
                    onChange={(e) => {
                      const questions = [...(draft.questions || [])];
                      questions[qIdx] = { ...questions[qIdx], section: e.target.value };
                      updateDraft({ questions });
                    }}
                    style={{ ...tplField, fontSize: 12, maxWidth: 200 }}
                  />
                </div>

                {/* Preview of control + editable options */}
                {(q.type === "LONG ANSWER") && (
                  <textarea disabled placeholder="Long answer…" rows={3} style={{ ...tplField, background: C.surface, color: C.mutedLight }} />
                )}
                {(q.type === "SHORT ANSWER" || !q.type) && (
                  <input disabled placeholder="Short answer…" style={{ ...tplField, background: C.surface, color: C.mutedLight }} />
                )}
                {q.type === "SONG LIST" && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                    {[1, 2, 3].map((n) => (
                      <input key={n} disabled placeholder={`${n}. Song title – Artist`} style={{ ...tplField, background: C.surface, color: C.mutedLight }} />
                    ))}
                    <div style={{ fontSize: 12, color: TEMPLATE_KIND_META.questionnaire.color, fontWeight: 700 }}>+ Add another song</div>
                  </div>
                )}
                {(q.type === "SINGLE SELECT" || q.type === "MULTI SELECT") && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                    {(q.options || []).map((opt, oIdx) => (
                      <div key={oIdx} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                        <span style={{ width: 14, height: 14, borderRadius: q.type === "MULTI SELECT" ? 3 : "50%", border: `1.5px solid ${C.borderLight}`, flexShrink: 0 }} />
                        <input value={opt} onChange={(e) => {
                          const questions = [...(draft.questions || [])];
                          const options = [...(questions[qIdx].options || [])];
                          options[oIdx] = e.target.value;
                          questions[qIdx] = { ...questions[qIdx], options };
                          updateDraft({ questions });
                        }} style={{ ...tplField, flex: 1 }} />
                        <button onClick={() => {
                          const questions = [...(draft.questions || [])];
                          questions[qIdx] = { ...questions[qIdx], options: (questions[qIdx].options || []).filter((_, i) => i !== oIdx) };
                          updateDraft({ questions });
                        }} style={{ background: "none", border: "none", color: C.mutedLight, cursor: "pointer" }}>✕</button>
                      </div>
                    ))}
                    <button onClick={() => {
                      const questions = [...(draft.questions || [])];
                      questions[qIdx] = { ...questions[qIdx], options: [...(questions[qIdx].options || []), "New option"] };
                      updateDraft({ questions });
                    }} style={{ background: "none", border: "none", color: TEMPLATE_KIND_META.questionnaire.color, fontWeight: 700, fontSize: 12, cursor: "pointer", fontFamily: BRAND_FONT, textAlign: "left", padding: 0 }}>+ Add option</button>
                  </div>
                )}
              </div>
            ))}
            <Btn variant="ghost" size="sm" onClick={() => updateDraft({
              questions: [...(draft.questions || []), { id: Date.now(), q: "New question", section: "General", type: "SHORT ANSWER", required: false, options: [] }],
            })}>+ Add question</Btn>
          </div>
        )}
      </div>
    );
  }

  // ── HUB + BROWSE ─────────────────────────────────────────
  const CATEGORY_CARDS = [
    {
      kind: "timeline",
      title: "Timelines",
      browse: "Browse Timelines",
      desc: "Run-of-show schedules for every kind of event — set the pacing once, reuse it forever.",
    },
    {
      kind: "contract",
      title: "Contracts",
      browse: "Browse Contracts",
      desc: "Service agreements, riders and payment terms — ready to send and sign.",
    },
    {
      kind: "music",
      title: "Music",
      browse: "Browse Music",
      desc: "Set lists and song cue sheets with energy pacing built in.",
    },
    {
      kind: "questionnaire",
      title: "Questionnaires",
      browse: "Browse Questionnaires",
      desc: "Client intake forms and post-event surveys, with the right question types.",
    },
  ];

  const newTemplateModal = showNew && (
    <Modal title="New Template" subtitle="Choose what you want to create" onClose={() => setShowNew(false)} width={480}>
      <div style={{ display: "grid", gap: 10 }}>
        {[
          { kind: "timeline", title: "Timeline", hint: "Run-of-show moments with times" },
          { kind: "contract", title: "Contract", hint: "Clauses, payment terms, signatures" },
          { kind: "music", title: "Music set-list", hint: "Blocks, songs, BPM, and energy cues" },
          { kind: "questionnaire", title: "Questionnaire", hint: "Client questions and answer types" },
        ].map((opt) => {
          const m = TEMPLATE_KIND_META[opt.kind];
          return (
            <button key={opt.kind} onClick={() => createBlank(opt.kind)} style={{
              display: "flex", alignItems: "center", gap: 14, width: "100%", textAlign: "left",
              padding: "14px 16px", borderRadius: BRAND_RADIUS.field, border: `1px solid ${C.border}`,
              background: C.surfaceAlt, cursor: "pointer", fontFamily: BRAND_FONT,
            }}
              onMouseEnter={(e) => { e.currentTarget.style.borderColor = m.color; e.currentTarget.style.background = m.soft; }}
              onMouseLeave={(e) => { e.currentTarget.style.borderColor = C.border; e.currentTarget.style.background = C.surfaceAlt; }}
            >
              <div style={{ width: 36, height: 36, borderRadius: BRAND_RADIUS.icon, background: m.soft, color: m.color, display: "flex", alignItems: "center", justifyContent: "center" }}>{m.icon}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, fontSize: 14, color: C.text }}>{opt.title}</div>
                <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{opt.hint}</div>
              </div>
              <span style={{ color: C.muted }}>›</span>
            </button>
          );
        })}
      </div>
    </Modal>
  );

  // Level 1 — Category hub
  if (!browseKind) {
    return (
      <div>
        {toast && <Toast message={toast} onClose={() => setToast(null)} />}
        {newTemplateModal}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 20, marginBottom: 24, flexWrap: "wrap" }}>
          <div style={{ minWidth: 240, flex: 1 }}>
            <h2 style={{ fontSize: 22, fontWeight: 900, letterSpacing: "-0.02em", marginBottom: 4, color: C.text, fontFamily: BRAND_FONT }}>Event Templates</h2>
            <p style={{ color: C.muted, fontSize: 13, lineHeight: 1.55, maxWidth: 520, margin: 0, fontFamily: BRAND_FONT }}>
              Your reusable building blocks. Pick a category to browse and drop any template straight into an event.
            </p>
          </div>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 12 }}>
            <Btn onClick={() => setShowNew(true)}>+ New Template</Btn>
            <div style={{ display: "flex", gap: 16, alignItems: "flex-end" }}>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 18, fontWeight: 900, color: C.text, letterSpacing: "-0.02em", lineHeight: 1, fontFamily: BRAND_FONT }}>{counts.all}</div>
                <div style={{ fontSize: 10, fontWeight: 700, color: C.muted, letterSpacing: "0.08em", marginTop: 4, fontFamily: BRAND_FONT }}>TEMPLATES</div>
              </div>
              <div style={{ width: 1, height: 32, background: C.border }} />
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 18, fontWeight: 900, color: C.text, letterSpacing: "-0.02em", lineHeight: 1, fontFamily: BRAND_FONT }}>{totalUsed}</div>
                <div style={{ fontSize: 10, fontWeight: 700, color: C.muted, letterSpacing: "0.08em", marginTop: 4, fontFamily: BRAND_FONT }}>TIMES USED</div>
              </div>
            </div>
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 14 }}>
          {CATEGORY_CARDS.map((card) => {
            const m = TEMPLATE_KIND_META[card.kind];
            const items = library.filter((i) => i.kind === card.kind);
            const preview = items.slice(0, 2);
            const extra = Math.max(0, items.length - 2);
            const hovered = hovId === card.kind;
            return (
              <button
                key={card.kind}
                onClick={() => { setBrowseKind(card.kind); setSearch(""); }}
                onMouseEnter={() => setHovId(card.kind)}
                onMouseLeave={() => setHovId(null)}
                style={{
                  textAlign: "left", cursor: "pointer", fontFamily: BRAND_FONT, position: "relative", overflow: "hidden",
                  background: C.surfaceAlt, border: `1px solid ${hovered ? m.color + "40" : C.border}`,
                  borderRadius: BRAND_RADIUS.card, padding: "20px 20px 16px",
                  boxShadow: hovered ? "0 8px 24px rgba(22,22,26,0.06)" : "0 1px 3px rgba(22,22,26,0.04)",
                  transition: "box-shadow 0.15s, border-color 0.15s, transform 0.15s",
                  transform: hovered ? "translateY(-1px)" : "none",
                  display: "flex", flexDirection: "column", minHeight: 200,
                }}
              >
                <div style={{
                  position: "absolute", top: -36, right: -36, width: 120, height: 120, borderRadius: "50%",
                  background: m.color + "14", pointerEvents: "none",
                }} />
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14, position: "relative" }}>
                  <div style={{
                    width: 40, height: 40, borderRadius: BRAND_RADIUS.icon, background: m.soft, color: m.color,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>{m.icon}</div>
                  <span style={{
                    fontSize: 10, fontWeight: 800, letterSpacing: "0.06em", color: m.color,
                    background: m.soft, padding: "4px 10px", borderRadius: BRAND_RADIUS.pill, fontFamily: BRAND_FONT,
                  }}>{items.length} TEMPLATES</span>
                </div>
                <div style={{ fontWeight: 800, fontSize: 16, color: C.text, letterSpacing: "-0.01em", marginBottom: 6, position: "relative", fontFamily: BRAND_FONT }}>{card.title}</div>
                <div style={{ fontSize: 13, color: C.muted, lineHeight: 1.5, marginBottom: 14, flex: 1, position: "relative", fontFamily: BRAND_FONT }}>{card.desc}</div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 14, position: "relative" }}>
                  {preview.map((p) => (
                    <span key={p.key} style={{
                      fontSize: 11, fontWeight: 600, color: C.muted, background: C.surface,
                      border: `1px solid ${C.border}`, borderRadius: 8, padding: "3px 8px", maxWidth: "100%",
                      overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontFamily: BRAND_FONT,
                    }}>{p.name}</span>
                  ))}
                  {extra > 0 && (
                    <span style={{ fontSize: 11, fontWeight: 700, color: C.mutedLight, padding: "3px 6px", fontFamily: BRAND_FONT }}>+{extra} more</span>
                  )}
                </div>
                <div style={{
                  display: "flex", alignItems: "center", gap: 6, fontSize: 13, fontWeight: 700,
                  color: m.color, position: "relative", fontFamily: BRAND_FONT,
                }}>
                  {card.browse} <span aria-hidden>→</span>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // Level 2 — Browse one category
  const browseMeta = TEMPLATE_KIND_META[browseKind];
  const browseTitle = CATEGORY_CARDS.find((c) => c.kind === browseKind)?.title || "Templates";

  return (
    <div>
      {toast && <Toast message={toast} onClose={() => setToast(null)} />}
      {newTemplateModal}

      <button onClick={() => { setBrowseKind(null); setSearch(""); }}
        style={{ background: "none", border: "none", color: C.muted, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: BRAND_FONT, padding: 0, marginBottom: 12 }}>
        ← Event Templates
      </button>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 20, marginBottom: 20, flexWrap: "wrap" }}>
        <div style={{ minWidth: 200, flex: 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
            <div style={{
              width: 36, height: 36, borderRadius: BRAND_RADIUS.icon, background: browseMeta.soft, color: browseMeta.color,
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>{browseMeta.icon}</div>
            <h2 style={{ fontSize: 22, fontWeight: 900, letterSpacing: "-0.02em", margin: 0, color: C.text, fontFamily: BRAND_FONT }}>{browseTitle}</h2>
          </div>
          <p style={{ color: C.muted, fontSize: 13, margin: 0, fontFamily: BRAND_FONT }}>
            {counts[browseKind]} templates · click any card to edit
          </p>
        </div>
        <Btn onClick={() => setShowNew(true)}>+ New Template</Btn>
      </div>

      <div style={{ display: "flex", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
        <div style={{ flex: 1, minWidth: 200, position: "relative" }}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={C.muted} strokeWidth="2" strokeLinecap="round" style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }}>
            <circle cx="11" cy="11" r="7" /><path d="M20 20l-3.5-3.5" />
          </svg>
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={`Search ${browseTitle.toLowerCase()}`}
            style={{ width: "100%", boxSizing: "border-box", padding: "10px 14px 10px 40px", border: `1px solid ${C.border}`, borderRadius: BRAND_RADIUS.field, background: C.surfaceAlt, fontSize: 13, fontFamily: BRAND_FONT, color: C.text, outline: "none" }} />
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))", gap: 12 }}>
        <button onClick={() => createBlank(browseKind)} style={{
          textAlign: "left", cursor: "pointer", fontFamily: BRAND_FONT, background: C.surfaceAlt,
          border: `1.5px dashed ${C.borderLight}`, borderRadius: BRAND_RADIUS.card, padding: "24px 18px", minHeight: 150,
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, color: C.muted,
        }}
          onMouseEnter={(e) => { e.currentTarget.style.borderColor = browseMeta.color; e.currentTarget.style.background = browseMeta.color + "08"; }}
          onMouseLeave={(e) => { e.currentTarget.style.borderColor = C.borderLight; e.currentTarget.style.background = C.surfaceAlt; }}
        >
          <div style={{ width: 36, height: 36, borderRadius: BRAND_RADIUS.icon, border: `1.5px dashed ${C.mutedLight}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, color: C.muted, marginBottom: 2 }}>+</div>
          <div style={{ fontWeight: 700, fontSize: 13, color: C.text }}>Blank template</div>
          <div style={{ fontSize: 12, color: C.muted }}>Start from scratch</div>
        </button>

        {filtered.map((item) => {
          const m = TEMPLATE_KIND_META[item.kind];
          const hovered = hovId === item.key;
          return (
            <div key={item.key} role="button" tabIndex={0} onClick={() => openDetail(item)} onKeyDown={(e) => e.key === "Enter" && openDetail(item)}
              onMouseEnter={() => setHovId(item.key)} onMouseLeave={() => setHovId(null)}
              style={{
                background: C.surfaceAlt, border: `1px solid ${hovered ? m.color + "55" : C.border}`, borderRadius: BRAND_RADIUS.card,
                padding: "16px 16px 12px", cursor: "pointer", boxShadow: hovered ? "0 8px 20px rgba(22,22,26,0.06)" : "0 1px 3px rgba(22,22,26,0.03)",
                transition: "box-shadow 0.15s, border-color 0.15s, transform 0.15s", transform: hovered ? "translateY(-1px)" : "none",
                display: "flex", flexDirection: "column", minHeight: 150, fontFamily: BRAND_FONT,
              }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                <div style={{ width: 32, height: 32, borderRadius: BRAND_RADIUS.icon, background: m.soft, color: m.color, display: "flex", alignItems: "center", justifyContent: "center" }}>{m.icon}</div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  {item.favorite && (
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="#EAB308" stroke="#EAB308" strokeWidth="1">
                      <path d="M12 2l2.9 6.6L22 10l-5 4.4L18.2 22 12 18.2 5.8 22 7 14.4 2 10l7.1-1.4L12 2z" />
                    </svg>
                  )}
                  <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: "0.06em", color: m.color, background: m.soft, padding: "3px 8px", borderRadius: 6 }}>{m.label}</span>
                </div>
              </div>
              <div style={{ fontWeight: 700, fontSize: 14, color: C.text, marginBottom: 4, letterSpacing: "-0.01em", lineHeight: 1.3 }}>{item.name}</div>
              <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.45, flex: 1 }}>{item.desc}</div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12, paddingTop: 10, borderTop: `1px solid ${C.border}` }}>
                <div style={{ fontSize: 11, color: C.mutedLight, fontWeight: 600 }}>Used {item.used}x · {item.edited}</div>
                <span style={{ color: m.color, fontSize: 15, fontWeight: 700 }}>›</span>
              </div>
            </div>
          );
        })}
      </div>

      {filtered.length === 0 && (
        <div style={{ textAlign: "center", padding: "48px 20px", color: C.muted, fontSize: 14 }}>No templates match “{search}”.</div>
      )}
    </div>
  );
};


// --- REPORTS --------------------------------------------------
const Reports = ({ setSection }) => {
  const { events, invoices, expenses, leads, clients, debriefs, mileage, payroll } = useApp();
  const [year, setYear] = useState(new Date().getFullYear());
  const [activeTab, setActiveTab] = useState("overview");

  const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

  const inYear  = (d) => d && new Date(d).getFullYear() === year;
  const fmt     = (n) => "$" + Number(n || 0).toLocaleString();
  const pct     = (a, b) => b === 0 ? null : ((a - b) / b * 100).toFixed(1);

  // ── revenue ───────────────────────────────────────────
  const yearEvents    = (events || []).filter(e => inYear(e.date));
  const totalRevenue  = yearEvents.reduce((s, e) => s + (Number(e.totalFee) || 0), 0);
  const totalCollected = collectedFromInvoices(
    (invoices || []).filter(i => {
      if (!year) return true;
      const y = new Date(i.issued || i.eventDate || "").getFullYear();
      return !isNaN(y) ? y === year : true;
    })
  );
  const totalExpenses = (expenses || []).filter(e => inYear(e.date)).reduce((s, e) => s + (Number(e.amount) || 0), 0);
  const totalMileage  = (mileage  || []).filter(m => inYear(m.date)).reduce((s, m) => s + (Number(m.miles) || 0), 0);
  const mileageValue  = totalMileage * 0.67;
  const totalPayroll  = (payroll  || []).filter(p => inYear(p.date)).reduce((s, p) => s + (Number(p.amount) || 0), 0);
  const netProfit     = totalRevenue - totalExpenses - totalPayroll;

  const prevRevenue   = (events || []).filter(e => e.date && new Date(e.date).getFullYear() === year - 1).reduce((s, e) => s + (Number(e.totalFee) || 0), 0);
  const revenueChange = pct(totalRevenue, prevRevenue);

  // ── event metrics ─────────────────────────────────────
  const avgEventValue = yearEvents.filter(e => e.totalFee > 0).length > 0
    ? Math.round(yearEvents.reduce((s, e) => s + (Number(e.totalFee) || 0), 0) / yearEvents.filter(e => e.totalFee > 0).length) : 0;

  const repeatClients = (() => {
    const map = {};
    (events || []).forEach(e => { if (e.client) map[e.client] = (map[e.client] || 0) + 1; });
    return Object.values(map).filter(c => c > 1).length;
  })();

  // ── leads ─────────────────────────────────────────────
  const yearLeads  = (leads || []).filter(l => inYear(l.createdAt));
  const convRate   = yearLeads.length > 0
    ? Math.round(yearLeads.filter(l => l.stage === "Booked").length / yearLeads.length * 100) : 0;

  // Pipeline revenue — all active leads (not year-filtered so pipeline is always current)
  const STAGE_PROBABILITY = { "New Inquiry": 0.10, "Quoted": 0.25, "Negotiating": 0.50, "Ready to Book": 0.75, "Booked": 1.0, "Lost": 0 };
  const activeLeadsAll = (leads || []).filter(l => l.stage !== "Lost");
  const totalPipelineValue = activeLeadsAll.reduce((s, l) => s + (Number(l.budget) || 0), 0);
  const weightedPipeline = activeLeadsAll.reduce((s, l) => s + (Number(l.budget) || 0) * (STAGE_PROBABILITY[l.stage] || 0.1), 0);
  const bookedLeadValue = (leads || []).filter(l => l.stage === "Booked").reduce((s, l) => s + (Number(l.budget) || 0), 0);
  const pipelineByStage = ["New Inquiry", "Quoted", "Negotiating", "Ready to Book"].map(stage => ({
    stage,
    count: activeLeadsAll.filter(l => (l.stage || "New Inquiry") === stage).length,
    value: activeLeadsAll.filter(l => (l.stage || "New Inquiry") === stage).reduce((s, l) => s + (Number(l.budget) || 0), 0),
    prob: STAGE_PROBABILITY[stage],
  }));
  const pipelineByType = (() => {
    const map = {};
    activeLeadsAll.forEach(l => { const t = l.event || "Other"; if (!map[t]) map[t] = { count: 0, value: 0 }; map[t].count++; map[t].value += Number(l.budget) || 0; });
    return Object.entries(map).map(([type, d]) => ({ type, ...d })).sort((a, b) => b.value - a.value);
  })();
  const pipelineBySource = (() => {
    const map = {};
    activeLeadsAll.forEach(l => { const s = l.source || "Direct"; if (!map[s]) map[s] = { count: 0, value: 0 }; map[s].count++; map[s].value += Number(l.budget) || 0; });
    return Object.entries(map).map(([source, d]) => ({ source, ...d })).sort((a, b) => b.value - a.value);
  })();

  // ── expenses ──────────────────────────────────────────
  const expByCategory = (() => {
    const map = {};
    (expenses || []).filter(e => inYear(e.date)).forEach(e => {
      const cat = e.category || "Other";
      map[cat] = (map[cat] || 0) + (Number(e.amount) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value })).sort((a,b) => b.value - a.value);
  })();

  // ── event breakdown ───────────────────────────────────
  const eventsByType = (() => {
    const map = {};
    yearEvents.forEach(e => { const t = e.type || "Other"; map[t] = (map[t] || 0) + 1; });
    return Object.entries(map).sort((a,b) => b[1] - a[1]);
  })();

  const topVenues = (() => {
    const map = {};
    yearEvents.forEach(e => { if (e.venue) map[e.venue] = (map[e.venue] || 0) + 1; });
    return Object.entries(map).sort((a,b) => b[1] - a[1]).slice(0, 8);
  })();

  const typeRevenue = (() => {
    const map = {};
    yearEvents.forEach(e => {
      const t = e.type || "Other";
      if (!map[t]) map[t] = { count: 0, revenue: 0 };
      map[t].count++;
      map[t].revenue += Number(e.totalFee) || 0;
    });
    return Object.entries(map).map(([type, d]) => ({ type, ...d })).sort((a,b) => b.revenue - a.revenue);
  })();

  // ── debriefs ─────────────────────────────────────────
  const debriefsAllArr = Object.entries(debriefs || {});
  const debriefsArr    = Object.values(debriefs || {});
  const avgRating      = debriefsArr.filter(d => d.overallRating > 0).length > 0
    ? (debriefsArr.filter(d => d.overallRating > 0).reduce((s, d) => s + d.overallRating, 0) / debriefsArr.filter(d => d.overallRating > 0).length).toFixed(1) : null;
  const rebookYes  = debriefsAllArr.filter(([,d]) => d.wouldRebook === "yes").length;
  const rebookRate = debriefsAllArr.length > 0 ? Math.round(rebookYes / debriefsAllArr.length * 100) : null;

  const TABS = [
    { id: "overview",       label: "Overview" },
    { id: "events",         label: "Events" },
    { id: "leads",          label: "Leads" },
    { id: "revenue",        label: "Revenue" },
    { id: "expenses",       label: "Expenses" },
    { id: "eventBreakdown", label: "Event Breakdown" },
  ];

  const KpiCard = ({ label, value, sub, color, change }) => (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: "18px 20px" }}>
      <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 8 }}>{label}</div>
      <div style={{ fontSize: 28, fontWeight: 900, color: color || C.text, letterSpacing: "-0.02em", marginBottom: 4 }}>{value}</div>
      {(sub || change !== undefined) && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          {sub && <span style={{ fontSize: 12, color: C.muted }}>{sub}</span>}
          {change !== null && change !== undefined && (
            <span style={{ fontSize: 11, fontWeight: 700, color: Number(change) >= 0 ? C.green : C.red }}>
              {Number(change) >= 0 ? "↑" : "↓"} {Math.abs(change)}% vs {year - 1}
            </span>
          )}
        </div>
      )}
    </div>
  );

  const StatRow = ({ label, value, color, sub }) => (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: `1px solid ${C.border}` }}>
      <div>
        <div style={{ fontSize: 13, fontWeight: 600 }}>{label}</div>
        {sub && <div style={{ fontSize: 11, color: C.muted }}>{sub}</div>}
      </div>
      <div style={{ fontSize: 14, fontWeight: 700, color: color || C.text }}>{value}</div>
    </div>
  );

  const Bar2 = ({ value, max, color }) => (
    <div style={{ background: C.border, borderRadius: 99, height: 6, overflow: "hidden", marginTop: 4 }}>
      <div style={{ height: "100%", width: (max > 0 ? Math.round(value / max * 100) : 0) + "%", background: color || C.accent, borderRadius: 99 }} />
    </div>
  );

  const noData = (msg) => (
    <div style={{ textAlign: "center", padding: "32px 20px", color: C.muted, fontSize: 13 }}>
      {msg}
    </div>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
        <div>
          <h2 style={{ fontSize: 22, fontWeight: 900, letterSpacing: "-0.02em", marginBottom: 4 }}>Reports</h2>
          <p style={{ color: C.muted, fontSize: 13 }}>Business performance and key metrics for {year}.</p>
        </div>
        <select value={year} onChange={e => setYear(Number(e.target.value))}
          style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 8,
            padding: "8px 14px", color: C.text, fontSize: 13, fontFamily: "inherit", outline: "none" }}>
          {[2023,2024,2025,2026,2027].map(y => <option key={y} value={y}>{y}</option>)}
        </select>
      </div>

      {/* Tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 24, flexWrap: "wrap" }}>
        {TABS.map(t => (
          <div key={t.id} onClick={() => setActiveTab(t.id)}
            style={{ padding: "8px 18px", borderRadius: 9, cursor: "pointer", fontSize: 13, fontWeight: 600, transition: "all 0.15s",
              background: activeTab === t.id ? C.accent : C.surface,
              color: activeTab === t.id ? "#fff" : C.muted,
              border: `1px solid ${activeTab === t.id ? C.accent : C.border}` }}>
            {t.label}
          </div>
        ))}
      </div>

      {/* ── OVERVIEW ── */}
      {activeTab === "overview" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Booked" value={fmt(totalRevenue)} color={C.green} change={revenueChange} />
            <KpiCard label="Collected" value={fmt(totalCollected)} color={C.accent} sub="Payments received" />
            <KpiCard label="Net Profit" value={fmt(netProfit)} color={netProfit >= 0 ? C.purple : C.red} />
            <KpiCard label="Total Events" value={yearEvents.length} color={C.accent} sub={`Avg ${fmt(avgEventValue)} / event`} />
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Expenses" value={fmt(totalExpenses)} color={C.orange} />
            <KpiCard label="Mileage" value={`${totalMileage.toLocaleString()} mi`} sub={`${fmt(mileageValue)} deductible`} color={C.teal} />
            <KpiCard label="Payroll" value={fmt(totalPayroll)} color={C.pink} />
            <KpiCard label="Repeat Clients" value={repeatClients} color={C.purple} sub="Clients with 2+ events" />
          </div>
          <Card>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Revenue Summary</div>
            <StatRow label="Total Booked" value={fmt(totalRevenue)} color={C.green} sub="From all events this year" />
            <StatRow label="Collected" value={fmt(totalCollected)} color={C.accent} sub="Deposits + balances received" />
            <StatRow label="Outstanding" value={fmt(Math.max(0, totalRevenue - totalCollected))} color={C.orange} sub="Awaiting collection" />
            <StatRow label="Total Expenses" value={fmt(totalExpenses)} color={C.red} />
            <StatRow label="Payroll" value={fmt(totalPayroll)} color={C.pink} />
            <StatRow label="Net Profit" value={fmt(netProfit)} color={netProfit >= 0 ? C.green : C.red} />
          </Card>
        </div>
      )}

      {/* ── EVENTS ── */}
      {activeTab === "events" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Events" value={yearEvents.length} color={C.accent} />
            <KpiCard label="Avg Event Value" value={fmt(avgEventValue)} color={C.green} />
            <KpiCard label="Unique Clients" value={new Set(yearEvents.map(e => e.client).filter(Boolean)).size} color={C.purple} />
            <KpiCard label="Repeat Clients" value={repeatClients} color={C.orange} />
          </div>
          {yearEvents.length === 0 ? noData("No events for this year") : (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
              <Card>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Events by Month</div>
                {MONTHS.map((m, mi) => {
                  const count = yearEvents.filter(e => new Date(e.date).getMonth() === mi).length;
                  return (
                    <div key={m} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                      <div style={{ fontSize: 12, color: C.muted, width: 28, flexShrink: 0 }}>{m}</div>
                      <div style={{ flex: 1, background: C.border, borderRadius: 99, height: 6, overflow: "hidden" }}>
                        <div style={{ height: "100%", width: (yearEvents.length > 0 ? count / Math.max(...MONTHS.map((_,i) => yearEvents.filter(e => new Date(e.date).getMonth() === i).length)) * 100 : 0) + "%", background: C.purple, borderRadius: 99 }} />
                      </div>
                      <div style={{ fontSize: 12, fontWeight: 700, width: 20, textAlign: "right" }}>{count || ""}</div>
                    </div>
                  );
                })}
              </Card>
              <Card>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Events by Type</div>
                {eventsByType.length === 0 ? noData("No event type data") : eventsByType.map(([type, count]) => (
                  <div key={type} style={{ marginBottom: 12 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                      <span style={{ fontWeight: 600 }}>{type}</span>
                      <span style={{ fontWeight: 700, color: C.accent }}>{count} event{count !== 1 ? "s" : ""}</span>
                    </div>
                    <Bar2 value={count} max={eventsByType[0][1]} color={C.accent} />
                  </div>
                ))}
              </Card>
            </div>
          )}
        </div>
      )}

      {/* ── LEADS ── */}
      {activeTab === "leads" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {/* KPI row */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Pipeline" value={fmt(totalPipelineValue)} color={C.green} sub={`${activeLeadsAll.length} active leads`} />
            <KpiCard label="Weighted Pipeline" value={fmt(Math.round(weightedPipeline))} color={C.accent} sub="Probability-adjusted" />
            <KpiCard label="Booked Value" value={fmt(bookedLeadValue)} color={C.purple} sub={`${(leads||[]).filter(l=>l.stage==="Booked").length} booked`} />
            <KpiCard label="Conversion Rate" value={`${convRate}%`} color={convRate >= 50 ? C.green : convRate >= 25 ? C.yellow : C.red} sub={`${yearLeads.length} leads this year`} />
          </div>

          {activeLeadsAll.length === 0 ? noData("No active leads in your pipeline") : (
            <>
              {/* Pipeline by stage — value + weighted */}
              <Card>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 6 }}>Pipeline by Stage</div>
                <div style={{ fontSize: 12, color: C.muted, marginBottom: 16 }}>Value at each stage × close probability = weighted forecast</div>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 10, marginBottom: 20 }}>
                  {pipelineByStage.map(({ stage, count, value, prob }) => {
                    const stageColors = { "New Inquiry": C.muted, "Quoted": C.accent, "Negotiating": C.yellow, "Ready to Book": C.green };
                    const col = stageColors[stage] || C.accent;
                    return (
                      <div key={stage} style={{ background: col + "0D", border: `1px solid ${col}30`, borderRadius: 10, padding: "14px 16px" }}>
                        <div style={{ fontSize: 11, fontWeight: 700, color: col, textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 8 }}>{stage}</div>
                        <div style={{ fontSize: 22, fontWeight: 900, color: C.text, marginBottom: 2 }}>{count}</div>
                        <div style={{ fontSize: 13, fontWeight: 700, color: col }}>{value > 0 ? fmt(value) : "—"}</div>
                        <div style={{ fontSize: 11, color: C.muted, marginTop: 4 }}>{Math.round(prob * 100)}% likely · {value > 0 ? fmt(Math.round(value * prob)) : "—"} weighted</div>
                      </div>
                    );
                  })}
                </div>
                {/* Weighted total bar */}
                <div style={{ background: C.surfaceAlt, borderRadius: 10, padding: "12px 16px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <div>
                    <div style={{ fontSize: 12, color: C.muted, marginBottom: 2 }}>Weighted Pipeline Total</div>
                    <div style={{ fontSize: 11, color: C.muted }}>Sum of (stage value × close probability)</div>
                  </div>
                  <div style={{ fontSize: 24, fontWeight: 900, color: C.accent }}>{fmt(Math.round(weightedPipeline))}</div>
                </div>
              </Card>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
                {/* By event type */}
                <Card>
                  <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Pipeline by Event Type</div>
                  {pipelineByType.length === 0 ? noData("No data") : pipelineByType.map(({ type, count, value }) => (
                    <div key={type} style={{ marginBottom: 14 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                        <span style={{ fontWeight: 600 }}>{type}</span>
                        <div style={{ textAlign: "right" }}>
                          <div style={{ fontWeight: 700, color: C.green }}>{value > 0 ? fmt(value) : "—"}</div>
                          <div style={{ fontSize: 11, color: C.muted }}>{count} lead{count !== 1 ? "s" : ""}</div>
                        </div>
                      </div>
                      <Bar2 value={value || count} max={pipelineByType[0].value || pipelineByType[0].count} color={C.green} />
                    </div>
                  ))}
                </Card>

                {/* By source */}
                <Card>
                  <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Pipeline by Source</div>
                  {pipelineBySource.length === 0 ? noData("No data") : pipelineBySource.map(({ source, count, value }) => (
                    <div key={source} style={{ marginBottom: 14 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                        <span style={{ fontWeight: 600 }}>{source}</span>
                        <div style={{ textAlign: "right" }}>
                          <div style={{ fontWeight: 700, color: C.accent }}>{value > 0 ? fmt(value) : "—"}</div>
                          <div style={{ fontSize: 11, color: C.muted }}>{count} lead{count !== 1 ? "s" : ""}</div>
                        </div>
                      </div>
                      <Bar2 value={value || count} max={pipelineBySource[0].value || pipelineBySource[0].count} color={C.accent} />
                    </div>
                  ))}
                </Card>
              </div>

              {/* All active leads table */}
              <Card style={{ padding: 0, overflow: "hidden" }}>
                <div style={{ padding: "16px 20px", borderBottom: `1px solid ${C.border}`, fontWeight: 700, fontSize: 14 }}>Active Pipeline — All Leads</div>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                  <thead>
                    <tr style={{ background: C.surfaceAlt }}>
                      {["Lead", "Stage", "Event Type", "Budget", "Probability", "Weighted Value"].map(h => (
                        <th key={h} style={{ padding: "9px 16px", textAlign: "left", fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: "0.06em" }}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {activeLeadsAll.sort((a, b) => (Number(b.budget) || 0) - (Number(a.budget) || 0)).map(l => {
                      const prob = STAGE_PROBABILITY[l.stage] || 0.1;
                      const budget = Number(l.budget) || 0;
                      const stageColors = { "New Inquiry": C.muted, "Quoted": C.accent, "Negotiating": C.yellow, "Ready to Book": C.green, "Booked": C.green };
                      const col = stageColors[l.stage] || C.muted;
                      return (
                        <tr key={l.id || l.name} style={{ borderTop: `1px solid ${C.border}` }}
                          onMouseEnter={e => e.currentTarget.style.background = C.surfaceHover}
                          onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                          <td style={{ padding: "10px 16px", fontWeight: 700 }}>{l.name}</td>
                          <td style={{ padding: "10px 16px" }}><Badge color={col}>{l.stage || "New Inquiry"}</Badge></td>
                          <td style={{ padding: "10px 16px", color: C.muted }}>{l.event || "—"}</td>
                          <td style={{ padding: "10px 16px", fontWeight: 700, color: budget > 0 ? C.green : C.muted }}>{budget > 0 ? fmt(budget) : "—"}</td>
                          <td style={{ padding: "10px 16px", color: C.muted }}>{Math.round(prob * 100)}%</td>
                          <td style={{ padding: "10px 16px", fontWeight: 700, color: budget > 0 ? C.accent : C.muted }}>{budget > 0 ? fmt(Math.round(budget * prob)) : "—"}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot>
                    <tr style={{ background: C.surfaceAlt, borderTop: `2px solid ${C.border}` }}>
                      <td colSpan={3} style={{ padding: "10px 16px", fontWeight: 700, fontSize: 13 }}>Total</td>
                      <td style={{ padding: "10px 16px", fontWeight: 900, color: C.green }}>{fmt(totalPipelineValue)}</td>
                      <td style={{ padding: "10px 16px" }} />
                      <td style={{ padding: "10px 16px", fontWeight: 900, color: C.accent }}>{fmt(Math.round(weightedPipeline))}</td>
                    </tr>
                  </tfoot>
                </table>
              </Card>
            </>
          )}
        </div>
      )}

      {/* ── REVENUE ── */}
      {activeTab === "revenue" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12 }}>
            <KpiCard label="Total Booked" value={fmt(totalRevenue)} color={C.green} change={revenueChange} />
            <KpiCard label="Collected" value={fmt(totalCollected)} color={C.accent} />
            <KpiCard label="Net Profit" value={fmt(netProfit)} color={netProfit >= 0 ? C.purple : C.red} />
          </div>
          <Card>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Monthly Revenue</div>
            {MONTHS.map((m, mi) => {
              const rev = yearEvents.filter(e => new Date(e.date).getMonth() === mi).reduce((s, e) => s + (Number(e.totalFee)||0), 0);
              const maxRev = Math.max(...MONTHS.map((_, i) => yearEvents.filter(e => new Date(e.date).getMonth() === i).reduce((s, e) => s + (Number(e.totalFee)||0), 0)), 1);
              return (
                <div key={m} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                  <div style={{ fontSize: 12, color: C.muted, width: 28, flexShrink: 0 }}>{m}</div>
                  <div style={{ flex: 1, background: C.border, borderRadius: 99, height: 8, overflow: "hidden" }}>
                    <div style={{ height: "100%", width: (rev / maxRev * 100) + "%", background: C.green, borderRadius: 99 }} />
                  </div>
                  <div style={{ fontSize: 12, fontWeight: 700, width: 70, textAlign: "right", color: rev > 0 ? C.green : C.muted }}>{rev > 0 ? fmt(rev) : ""}</div>
                </div>
              );
            })}
          </Card>
        </div>
      )}

      {/* ── EXPENSES ── */}
      {activeTab === "expenses" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Expenses" value={fmt(totalExpenses)} color={C.red} />
            <KpiCard label="Mileage Deduction" value={fmt(mileageValue)} sub={`${totalMileage.toLocaleString()} miles`} color={C.teal} />
            <KpiCard label="Payroll Paid" value={fmt(totalPayroll)} color={C.orange} />
            <KpiCard label="Total Deductions" value={fmt(totalExpenses + mileageValue + totalPayroll)} color={C.purple} />
          </div>
          {expByCategory.length === 0 ? noData("No expenses logged for this year") : (
            <Card>
              <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Expenses by Category</div>
              {expByCategory.map(({ name, value }) => (
                <div key={name} style={{ marginBottom: 12 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                    <span style={{ fontWeight: 600 }}>{name}</span>
                    <span style={{ fontWeight: 700, color: C.red }}>{fmt(value)}</span>
                  </div>
                  <Bar2 value={value} max={expByCategory[0].value} color={C.orange} />
                </div>
              ))}
            </Card>
          )}
        </div>
      )}

      {/* ── EVENT BREAKDOWN ── */}
      {activeTab === "eventBreakdown" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
            <KpiCard label="Total Events" value={yearEvents.length} color={C.accent} />
            <KpiCard label="Avg Event Value" value={fmt(avgEventValue)} color={C.green} />
            <KpiCard label="Unique Clients" value={new Set(yearEvents.map(e => e.client).filter(Boolean)).size} color={C.purple} />
            <KpiCard label="Repeat Clients" value={repeatClients} color={C.orange} />
          </div>
          {yearEvents.length === 0 ? noData("No events for this year") : (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
              <Card>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Revenue by Event Type</div>
                {typeRevenue.length === 0 ? noData("No data") : typeRevenue.map(d => (
                  <div key={d.type} style={{ marginBottom: 14 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                      <span style={{ fontWeight: 600 }}>{d.type}</span>
                      <div style={{ textAlign: "right" }}>
                        <div style={{ fontWeight: 700, color: C.green }}>{fmt(d.revenue)}</div>
                        <div style={{ fontSize: 11, color: C.muted }}>{d.count} event{d.count !== 1 ? "s" : ""}</div>
                      </div>
                    </div>
                    <Bar2 value={d.revenue} max={typeRevenue[0].revenue} color={C.green} />
                  </div>
                ))}
              </Card>
              <Card>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Top Venues</div>
                {topVenues.length === 0 ? noData("No venue data") : topVenues.map(([venue, count]) => (
                  <div key={venue} style={{ marginBottom: 12 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
                      <span style={{ fontWeight: 600 }}>{venue}</span>
                      <span style={{ fontWeight: 700, color: C.accent }}>{count} event{count !== 1 ? "s" : ""}</span>
                    </div>
                    <Bar2 value={count} max={topVenues[0][1]} color={C.accent} />
                  </div>
                ))}
              </Card>
              <Card style={{ gridColumn: "1 / -1" }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Invoice Status</div>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
                  {[["Paid", C.green], ["Sent", C.accent], ["Overdue", C.red], ["Draft", C.muted]].map(([status, color]) => {
                    const count = (invoices || []).filter(i => i.status === status).length;
                    return (
                      <div key={status} style={{ background: C.surfaceAlt, border: `1px solid ${C.border}`, borderRadius: 10, padding: "14px 16px", textAlign: "center" }}>
                        <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, textTransform: "uppercase", marginBottom: 8 }}>{status}</div>
                        <div style={{ fontSize: 24, fontWeight: 900, color }}>{count}</div>
                      </div>
                    );
                  })}
                </div>
              </Card>
            </div>
          )}
        </div>
      )}

    </div>
  );
};
const SUIT_STATUSES = [
  { label: "Clean & Ready",        color: "#16A34A", bg: "#16A34A15", icon: "" },
  { label: "Drop Off At Cleaners", color: "#6C4DF6", bg: "#6C4DF615", icon: "" },
  { label: "At the Cleaners",      color: "#7C5BF5", bg: "#7C5BF515", icon: "" },
  { label: "Needs Washing",        color: "#EA580C", bg: "#EA580C15", icon: "" },
  { label: "Dirty",                color: "#DC2626", bg: "#DC262615", icon: "" },
];

const getStatusMeta = (status) => SUIT_STATUSES.find(s => s.label === status) || SUIT_STATUSES[0];

// Modal for setting drop-off date
const DropOffModal = ({ item, onClose, onSave }) => {
  const [date, setDate] = useState(item.dropOffDate || "");
  return (
    <Modal title="Schedule Drop Off" subtitle={`Set the drop-off date for ${item.name}`} onClose={onClose}>
      <div style={{ marginBottom: 20 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Drop-Off Date</label>
        <input type="date" value={date} onChange={e => setDate(e.target.value)}
          style={{ width: "100%", padding: "10px 12px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.surface, fontSize: 13, color: C.text, boxSizing: "border-box" }} />
        <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>This will appear on your dashboard calendar as a reminder.</div>
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
        <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        <Btn onClick={() => { onSave(date); onClose(); }} disabled={!date}>Save Drop-Off Date</Btn>
      </div>
    </Modal>
  );
};

// Modal for setting pickup date
const PickupModal = ({ item, onClose, onSave }) => {
  const { timeFormat } = useApp();
  const [date, setDate] = useState(item.pickupDate || "");
  const [time, setTime] = useState(item.pickupTime || "");
  return (
    <Modal title="Set Pickup Date" subtitle={`When will ${item.name} be ready?`} onClose={onClose}>
      <div style={{ marginBottom: 16 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Pickup Date</label>
        <input type="date" value={date} onChange={e => setDate(e.target.value)}
          style={{ width: "100%", padding: "10px 12px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.surface, fontSize: 13, color: C.text, boxSizing: "border-box" }} />
      </div>
      <div style={{ marginBottom: 20 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Pickup Time (optional)</label>
        <TimeInput value={time} onChange={setTime} timeFormat={timeFormat} inputStyle={{ width: "100%", padding: "10px 12px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.surface, fontSize: 13, color: C.text, boxSizing: "border-box" }} />
        <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>A reminder will appear on your dashboard calendar.</div>
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
        <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        <Btn onClick={() => { onSave(date, time); onClose(); }} disabled={!date}>Set Pickup Reminder</Btn>
      </div>
    </Modal>
  );
};

const WardrobeModal = ({ suit, onClose, onSave, events, categories }) => {
  const [form, setForm] = useState(suit || {
    name: "", category: "", color: "", notes: "", status: "Clean & Ready", assignedEventId: "",
  });
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const upcoming = (events || []).filter(e => e.date >= new Date().toISOString().slice(0,10)).sort((a,b) => a.date > b.date ? 1 : -1);
  const cats = categories || DEFAULT_WARDROBE_CATEGORIES;
  const iStyle = { width: "100%", padding: "10px 12px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.surface, fontSize: 13, color: C.text, boxSizing: "border-box", fontFamily: "inherit" };
  return (
    <Modal title={suit ? "Edit Item" : "Add Wardrobe Item"} subtitle={suit ? "Update item details" : "Add a clothing item to your wardrobe"} onClose={onClose}>
      <Input label="Item Name" value={form.name} onChange={v => set("name", v)} placeholder="e.g. Black Tuxedo Jacket, White Dress Shirt" />
      <div style={{ marginBottom: 16 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Category</label>
        <select value={form.category || ""} onChange={e => set("category", e.target.value)} style={iStyle}>
          <option value="">— Select Category —</option>
          {cats.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>
      <Input label="Color / Description" value={form.color} onChange={v => set("color", v)} placeholder="e.g. Midnight Black, Charcoal, Navy Blue" />
      <div style={{ marginBottom: 16 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 8 }}>Status</label>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          {SUIT_STATUSES.map(s => (
            <div key={s.label} onClick={() => set("status", s.label)}
              style={{ padding: "10px 14px", borderRadius: 10, border: `2px solid ${form.status === s.label ? s.color : C.border}`,
                background: form.status === s.label ? s.bg : C.surface, cursor: "pointer",
                display: "flex", alignItems: "center", gap: 8, transition: "all 0.15s" }}>
              <span style={{ fontSize: 16 }}>{s.icon}</span>
              <span style={{ fontSize: 12, fontWeight: 600, color: form.status === s.label ? s.color : C.text }}>{s.label}</span>
            </div>
          ))}
        </div>
      </div>
      <div style={{ marginBottom: 16 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Assign to Event</label>
        <select value={form.assignedEventId || ""} onChange={e => set("assignedEventId", e.target.value)} style={iStyle}>
          <option value="">— Unassigned —</option>
          {upcoming.map(ev => (
            <option key={ev.id} value={ev.id}>{ev.date} — {ev.name || ev.clientName || "Event"}</option>
          ))}
        </select>
      </div>
      <div style={{ marginBottom: 20 }}>
        <label style={{ fontSize: 13, fontWeight: 600, color: C.muted, display: "block", marginBottom: 6 }}>Notes</label>
        <textarea value={form.notes} onChange={e => set("notes", e.target.value)}
          placeholder="e.g. Missing button on left cuff, needs alterations..." rows={3}
          style={{ ...iStyle, resize: "vertical" }} />
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
        <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        <Btn onClick={() => { if (!form.name.trim()) return; onSave(form); }}>Save Item</Btn>
      </div>
    </Modal>
  );
};

const Wardrobe = () => {
  const { wardrobe, setWardrobe, events, setEvents, wardrobeCategories } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [activeStatus, setActiveStatus] = useState("All");
  const [activeCategory, setActiveCategory] = useState("All");
  const [dropOffItem, setDropOffItem] = useState(null);
  const [pickupItem, setPickupItem] = useState(null);
  const [toast, setToast] = useState("");

  const cats = wardrobeCategories || DEFAULT_WARDROBE_CATEGORIES;
  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(""), 2500); };

  const statusTabs = ["All", "Clean & Ready", "Drop Off At Cleaners", "At the Cleaners", "Needs Washing", "Dirty"];

  const updateItem = (id, patch) => setWardrobe(prev => prev.map(s => s.id === id ? { ...s, ...patch } : s));

  // Filter by status then category
  const byStatus = activeStatus === "All" ? wardrobe : wardrobe.filter(s => s.status === activeStatus);
  const displayed = activeCategory === "All" ? byStatus : byStatus.filter(s => s.category === activeCategory);

  const getEventName = (id) => {
    const ev = (events || []).find(e => String(e.id) === String(id));
    if (!ev) return null;
    return `${ev.date} — ${ev.name || ev.client || "Event"}`;
  };

  const handleSave = (form) => {
    if (editItem) {
      const prevAssigned = editItem.assignedEventId || "";
      const nextAssigned = form.assignedEventId || "";
      updateItem(editItem.id, form);
      if (!eqIdMatch(prevAssigned, nextAssigned)) {
        if (prevAssigned) syncWardrobeToEvent(editItem.id, prevAssigned, false, setWardrobe, setEvents);
        if (nextAssigned) syncWardrobeToEvent(editItem.id, nextAssigned, true, setWardrobe, setEvents);
      }
      showToast("Item updated!");
    } else {
      const newId = Date.now();
      const newItem = { ...form, id: newId };
      setWardrobe(prev => [...prev, newItem]);
      if (form.assignedEventId) syncWardrobeToEvent(newId, form.assignedEventId, true, setWardrobe, setEvents);
      showToast("Item added!");
    }
    setEditItem(null);
    setShowModal(false);
  };

  const readyCount   = wardrobe.filter(s => s.status === "Clean & Ready").length;
  const dropOffCount = wardrobe.filter(s => s.status === "Drop Off At Cleaners").length;
  const cleanerCount = wardrobe.filter(s => s.status === "At the Cleaners").length;
  const dirtyCount   = wardrobe.filter(s => ["Needs Washing","Dirty"].includes(s.status)).length;

  return (
    <div>
      {toast && <Toast msg={toast} onClose={() => setToast("")} />}
      {(showModal || editItem) && (
        <WardrobeModal
          suit={editItem}
          events={events}
          categories={cats}
          onClose={() => { setShowModal(false); setEditItem(null); }}
          onSave={handleSave}
        />
      )}
      {dropOffItem && (
        <DropOffModal
          item={dropOffItem}
          onClose={() => setDropOffItem(null)}
          onSave={(date) => {
            updateItem(dropOffItem.id, { status: "Drop Off At Cleaners", dropOffDate: date });
            showToast(`Drop-off scheduled for ${date}`);
          }}
        />
      )}
      {pickupItem && (
        <PickupModal
          item={pickupItem}
          onClose={() => setPickupItem(null)}
          onSave={(date, time) => {
            updateItem(pickupItem.id, { pickupDate: date, pickupTime: time });
            showToast(`Pickup reminder set for ${date}${time ? " at " + time : ""}`);
          }}
        />
      )}

      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
        <div>
          <h2 style={{ fontSize: 22, fontWeight: 900, marginBottom: 4 }}>Wardrobe</h2>
          <p style={{ color: C.muted, fontSize: 13 }}>Track every clothing item — always know what's clean, at the cleaners, or needs attention</p>
        </div>
        <Btn size="sm" onClick={() => { setEditItem(null); setShowModal(true); }}>+ Add Item</Btn>
      </div>

      {/* Stats */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 20 }}>
        <Stat label="Clean & Ready" value={readyCount.toString()} color={C.green} />
        <Stat label="Drop Off Needed" value={dropOffCount.toString()} color="#6C4DF6" />
        <Stat label="At the Cleaners" value={cleanerCount.toString()} color={C.purple} />
        <Stat label="Needs Attention" value={dirtyCount.toString()} color={C.orange} />
      </div>

      {/* Status tabs */}
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
        {statusTabs.map(t => {
          const meta = t !== "All" ? getStatusMeta(t) : null;
          const active = activeStatus === t;
          const count = t === "All" ? wardrobe.length : wardrobe.filter(s => s.status === t).length;
          return (
            <div key={t} onClick={() => setActiveStatus(t)}
              style={{ padding: "6px 14px", borderRadius: 20, cursor: "pointer", fontSize: 12, fontWeight: 600,
                background: active ? (meta ? meta.color : C.accent) : C.surface,
                color: active ? "#fff" : C.muted,
                border: `1px solid ${active ? "transparent" : C.border}`,
                display: "flex", alignItems: "center", gap: 6, transition: "all 0.15s" }}>
              {meta && <span>{meta.icon}</span>}
              {t}
              <span style={{ background: active ? "rgba(255,255,255,0.25)" : C.surfaceAlt, borderRadius: 8, padding: "1px 6px", fontSize: 10 }}>{count}</span>
            </div>
          );
        })}
      </div>

      {/* Category filter bar */}
      {wardrobe.length > 0 && (
        <div style={{ display: "flex", gap: 6, marginBottom: 20, flexWrap: "wrap", padding: "10px 14px", background: C.surfaceAlt, borderRadius: 10, border: `1px solid ${C.border}` }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: "0.05em", alignSelf: "center", marginRight: 4 }}>Category:</span>
          {["All", ...cats].map(cat => (
            <div key={cat} onClick={() => setActiveCategory(cat)}
              style={{ padding: "4px 12px", borderRadius: 20, cursor: "pointer", fontSize: 12, fontWeight: 600,
                background: activeCategory === cat ? C.accent : C.surface,
                color: activeCategory === cat ? "#fff" : C.muted,
                border: `1px solid ${activeCategory === cat ? "transparent" : C.border}`,
                transition: "all 0.15s" }}>
              {cat}
              {cat !== "All" && (
                <span style={{ marginLeft: 5, fontSize: 10, opacity: 0.7 }}>
                  {wardrobe.filter(s => s.category === cat).length}
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Empty state */}
      {wardrobe.length === 0 ? (
        <Card style={{ textAlign: "center", padding: 56 }}>
          <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 8 }}>No wardrobe items yet</div>
          <div style={{ color: C.muted, fontSize: 13, marginBottom: 20 }}>Add your suits, shirts, and accessories — track what's clean, dirty, or at the cleaners so you're never caught off guard before a gig</div>
          <Btn onClick={() => setShowModal(true)}>+ Add Your First Item</Btn>
        </Card>
      ) : displayed.length === 0 ? (
        <Card style={{ textAlign: "center", padding: 40 }}>
          <div style={{ color: C.muted, fontSize: 14 }}>No items match this filter</div>
        </Card>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: 16 }}>
          {displayed.map(item => {
            const meta = getStatusMeta(item.status);
            const eventName = item.assignedEventId ? getEventName(item.assignedEventId) : null;
            return (
              <Card key={item.id} style={{ padding: 20, position: "relative" }}>
                {/* Status bar */}
                <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, borderRadius: "12px 12px 0 0", background: meta.color }} />

                {/* Header row */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10, marginTop: 4 }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 800, fontSize: 15, marginBottom: 2 }}>{item.name}</div>
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                      {item.category && <span style={{ fontSize: 11, color: C.accent, background: C.accentDim, borderRadius: 6, padding: "2px 8px", fontWeight: 600 }}>{item.category}</span>}
                      {item.color && <span style={{ fontSize: 11, color: C.muted }}>{item.color}</span>}
                    </div>
                  </div>
                  <span style={{ fontSize: 11, fontWeight: 700, color: meta.color, background: meta.bg,
                    padding: "4px 10px", borderRadius: 20, whiteSpace: "nowrap",
                    border: `1px solid ${meta.color}33`, flexShrink: 0, marginLeft: 10 }}>
                    {meta.icon} {meta.label}
                  </span>
                </div>

                {/* Assigned event */}
                {eventName && (
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 10,
                    background: C.accentDim, borderRadius: 8, padding: "7px 10px" }}>
                    <span style={{ fontSize: 13 }}></span>
                    <span style={{ fontSize: 12, color: C.accent, fontWeight: 600 }}>{eventName}</span>
                  </div>
                )}

                {/* Drop-off date */}
                {item.dropOffDate && item.status === "Drop Off At Cleaners" && (
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 10,
                    background: "#6C4DF610", borderRadius: 8, padding: "7px 10px", border: "1px solid #6C4DF630" }}>
                    <span style={{ fontSize: 13 }}></span>
                    <span style={{ fontSize: 12, color: "#6C4DF6", fontWeight: 600 }}>Drop off: {item.dropOffDate}</span>
                  </div>
                )}

                {/* Pickup date */}
                {item.pickupDate && item.status === "At the Cleaners" && (
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 10,
                    background: C.purple + "10", borderRadius: 8, padding: "7px 10px", border: `1px solid ${C.purple}30` }}>
                    <span style={{ fontSize: 13 }}></span>
                    <span style={{ fontSize: 12, color: C.purple, fontWeight: 600 }}>
                      Pickup: {item.pickupDate}{item.pickupTime ? " at " + item.pickupTime : ""}
                    </span>
                  </div>
                )}

                {/* Notes */}
                {item.notes && (
                  <div style={{ fontSize: 12, color: C.muted, background: C.surfaceAlt,
                    borderRadius: 8, padding: "8px 10px", marginBottom: 10, lineHeight: 1.5 }}>
                    {item.notes}
                  </div>
                )}

                {/* Quick action buttons */}
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", borderTop: `1px solid ${C.border}`, paddingTop: 12 }}>
                  <Btn size="sm" variant="ghost" onClick={() => { setEditItem(item); setShowModal(true); }}>✏️ Edit</Btn>

                  {/* Clean & Ready → quick status buttons */}
                  {item.status === "Clean & Ready" && (<>
                    <Btn size="sm" variant="ghost" onClick={() => setDropOffItem(item)}> To Cleaners</Btn>
                    <Btn size="sm" variant="ghost" onClick={() => { updateItem(item.id, { status: "Needs Washing" }); showToast("Marked as needs washing"); }}> Needs Wash</Btn>
                    <Btn size="sm" variant="ghost" onClick={() => { updateItem(item.id, { status: "Dirty" }); showToast("Marked dirty"); }}>⚠️ Dirty</Btn>
                  </>)}

                  {/* Needs Washing / Dirty → send to cleaners or mark dirty */}
                  {["Needs Washing","Dirty"].includes(item.status) && (<>
                    <Btn size="sm" variant="ghost" onClick={() => setDropOffItem(item)}> Send to Cleaners</Btn>
                    {item.status === "Needs Washing" && <Btn size="sm" variant="ghost" onClick={() => { updateItem(item.id, { status: "Dirty" }); showToast("Marked dirty"); }}>⚠️ Dirty</Btn>}
                    {item.status === "Dirty" && <Btn size="sm" variant="ghost" onClick={() => { updateItem(item.id, { status: "Needs Washing" }); showToast("Marked needs washing"); }}> Needs Wash</Btn>}
                  </>)}

                  {/* Drop Off At Cleaners → mark completed drop-off */}
                  {item.status === "Drop Off At Cleaners" && (<>
                    <Btn size="sm" onClick={() => { setPickupItem(item); updateItem(item.id, { status: "At the Cleaners" }); showToast("Dropped off! Set pickup date."); }}>✅ Dropped Off</Btn>
                    {!item.dropOffDate && <Btn size="sm" variant="ghost" onClick={() => setDropOffItem(item)}> Set Date</Btn>}
                  </>)}

                  {/* At the Cleaners → set pickup or mark ready */}
                  {item.status === "At the Cleaners" && (<>
                    {!item.pickupDate && <Btn size="sm" variant="ghost" onClick={() => setPickupItem(item)}> Set Pickup</Btn>}
                    <Btn size="sm" onClick={() => { updateItem(item.id, { status: "Clean & Ready", dropOffDate: null, pickupDate: null, pickupTime: null }); showToast(`${item.name} is clean & ready!`); }}>✅ Picked Up</Btn>
                  </>)}

                  <div style={{ flex: 1 }} />
                  <Btn size="sm" variant="danger" onClick={() => { setWardrobe(prev => prev.filter(s => s.id !== item.id)); showToast("Item removed."); }}>✕</Btn>
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};


